document.addEventListener("DOMContentLoaded",()=>{const a=[{label:"Height",value:"7,272 m",detail:"Mana Peak is one of the high summits of the Garhwal Himalayas."},{label:"State",value:"Uttarakhand",detail:"The peak is associated with the Chamoli district / Mana region of Uttarakhand."},{label:"Range",value:"Garhwal Himalayas",detail:"Part of the greater Himalayan system close to major high-altitude passes."},{label:"Nearby region",value:"Mana Pass",detail:"The area is known for remote trans-Himalayan terrain near the Indo-Tibetan border."},{label:"Route type",value:"Expedition climb",detail:"High-altitude snow, ice, glacier, and weather planning are essential."},{label:"Best suited for",value:"Experienced teams",detail:"This is educational content, not a casual trekking recommendation."}],e=[{title:"Garhwal Himalaya",image:"../../assets/travel_mountains.png",caption:"Snow-covered high Himalayan terrain."},{title:"Remote approach",image:"../../assets/travel_hidden.png",caption:"Long valleys and high-altitude routes shape the journey."},{title:"Expedition camp",image:"../../assets/hero_banner.png",caption:"Staged camps and acclimatisation are essential."},{title:"Mountain ridge",image:"../../assets/travel_mountains.png",caption:"Summit routes demand careful planning and safe weather windows."}],t=a=>String(a).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");document.getElementById("facts-grid").innerHTML=a.map(a=>`\n    <article class="fact-card">\n      <span>${t(a.label)}</span>\n      <strong>${t(a.value)}</strong>\n      <p>${t(a.detail)}</p>\n    </article>\n  `).join(""),document.getElementById("timeline").innerHTML=[{title:"Himalayan setting",text:"Mana Peak rises in the Garhwal Himalayas, one of India's most dramatic high-mountain regions."},{title:"Borderland geography",text:"Its landscape is shaped by high passes, glaciers, cold winds, and remote approach routes."},{title:"Expedition focus",text:"The peak is suitable only for trained mountaineering teams with high-altitude preparation."},{title:"Educational value",text:"Mana Peak helps learners understand Indian Himalayan geography, elevation, and expedition planning."}].map((a,e)=>`\n    <article class="timeline-item">\n      <span>0${e+1}</span>\n      <h3>${t(a.title)}</h3>\n      <p>${t(a.text)}</p>\n    </article>\n  `).join(""),document.getElementById("gallery-grid").innerHTML=e.map(a=>`\n    <article class="gallery-card">\n      <img src="${t(a.image)}" alt="${t(a.title)}" onerror="this.src='../../assets/hero_banner.png'">\n      <div>\n        <h3>${t(a.title)}</h3>\n        <p>${t(a.caption)}</p>\n      </div>\n    </article>\n  `).join(""),window.ManaPeakMountainPage={facts:()=>[...a],gallery:()=>[...e]}});